SELECT CASE WHEN discount_pct >= 0.27 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, COUNT(*) FILTER (WHERE promo_code = 'WELCOME5') AS welcome5_rows, ROUND(AVG(discount_pct), 2) AS avg_discount_pct, ROUND(AVG(discount_pct), 2) AS avg_discount_pct_2, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'BUNDLE' THEN 1 END), 0), 2) AS discount_pct_per_bundle, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes_2 FROM promotions GROUP BY CASE WHEN discount_pct >= 0.27 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY avg_discount_pct_2 DESC NULLS FIRST;
